package run.ikaros.game; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Mono; import run.ikaros.common.ConflictException; import run.ikaros.common.NotFoundException;
@Service public class PersistentGameAssetIntegrityService implements GameAssetIntegrityService{private final GameAssetRepository assets;public PersistentGameAssetIntegrityService(GameAssetRepository a){assets=a;}@Override public Mono<GameAssetView> verify(UUID o,UUID id,VerifyGameAssetChecksumRequest r){return owned(o,id).map(a->{GameAssetAvailability state=r.matched()?GameAssetAvailability.AVAILABLE:GameAssetAvailability.CORRUPTED;return new GameAssetEntity(a.id(),a.ownerId(),a.gameId(),a.versionId(),a.attachmentId(),a.category(),a.displayName(),r.algorithm(),r.value(),state,a.entityVersion());}).flatMap(assets::save).map(this::view);}@Override public Mono<GameAssetView> requestRestore(UUID o,UUID id){return owned(o,id).flatMap(a->{if(a.availability()!=GameAssetAvailability.ARCHIVED)return Mono.error(new ConflictException("只有 ARCHIVED Asset 可以请求恢复"));return assets.save(new GameAssetEntity(a.id(),a.ownerId(),a.gameId(),a.versionId(),a.attachmentId(),a.category(),a.displayName(),a.checksumAlgorithm(),a.checksumValue(),GameAssetAvailability.RESTORING,a.entityVersion()));}).map(this::view);}private Mono<GameAssetEntity> owned(UUID o,UUID id){return assets.findById(id).filter(a->a.ownerId().equals(o)).switchIfEmpty(Mono.error(new NotFoundException("Game Asset 不存在或无权访问")));}private GameAssetView view(GameAssetEntity e){return new GameAssetView(e.id(),e.gameId(),e.versionId(),e.attachmentId(),e.category(),e.displayName(),e.checksumAlgorithm(),e.checksumValue(),e.availability());}}
